<?php
require __DIR__.'/bootstrap.php';require_perm('invoices.view');$s=$pdo->prepare('SELECT i.*,s.shipment_date,s.awb,s.mark,s.pcs,s.kg,s.rate,s.total shipment_total,s.paid_dxb,s.balance_mgq,s.extra,s.sender,s.tell,s.receiver,s.description,s.fly_awb_no,s.status shipment_status,a.name airline,a.code airline_code FROM shipment_invoices i JOIN shipments s ON s.id=i.shipment_id JOIN airlines a ON a.id=s.airline_id WHERE i.id=?');$s->execute([(int)($_GET['id']??0)]);$r=$s->fetch();if(!$r){http_response_code(404);exit('Invoice not found.');}$p=$pdo->prepare('SELECT p.*,u.name received_by FROM payments p JOIN users u ON u.id=p.received_by WHERE p.shipment_id=? ORDER BY p.paid_at DESC');$p->execute([$r['shipment_id']]);$payments=$p->fetchAll();$title='Invoice details';require __DIR__.'/partials/header.php';?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 fw-bold mb-1"><?=e($r['invoice_no'])?></h1><p class="text-secondary mb-0">Complete invoice and shipment information.</p></div><div><a class="btn btn-outline-secondary" href="shipment_invoices.php">Back</a><a class="btn btn-primary" target="_blank" href="invoice_print.php?id=<?=$r['id']?>">Print</a></div></div><div class="card p-3 p-lg-4 mb-4"><div class="row g-4"><div class="col-md-4"><small class="text-secondary">Shipment</small><h5><?=e($r['awb'])?></h5><div><?=app_date($r['shipment_date'])?> · <?=e($r['shipment_status'])?></div><div><?=e($r['airline'])?> (<?=e($r['airline_code'])?>)</div><div>Fly AWB: <?=e($r['fly_awb_no']?:'—')?></div></div><div class="col-md-4"><small class="text-secondary">Sender / receiver</small><h5><?=e($r['sender'])?></h5><div><?=e($r['tell']?:'—')?></div><div>To: <?=e($r['receiver'])?></div></div><div class="col-md-4"><small class="text-secondary">Invoice</small><h5><?=e($r['status'])?></h5><div>Issued: <?=app_date($r['issue_date'])?></div><div>Due: <?=app_date($r['due_date'])?></div></div></div></div><div class="card p-3 p-lg-4 mb-4"><h2 class="h5">Cargo charges</h2><div class="table-responsive"><table class="table"><thead><tr><th>Mark</th><th>PCS</th><th>KG</th><th>Rate</th><th>Total</th><th>Paid DXB</th><th>Extra</th><th>Balance MGQ</th></tr></thead><tbody><tr><td><?=e($r['mark']?:'—')?></td><td><?=e($r['pcs'])?></td><td><?=e($r['kg'])?></td><td><?=money($r['rate'])?></td><td><?=money($r['shipment_total'])?></td><td><?=money($r['paid_dxb'])?></td><td><?=money($r['extra'])?></td><td class="fw-bold text-danger"><?=money($r['balance_mgq'])?></td></tr></tbody></table></div><p class="mb-0"><strong>Description:</strong> <?=e($r['description'])?></p></div><div class="card p-3 p-lg-4"><h2 class="h5">Payment history</h2><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Location</th><th>Method</th><th>Reference</th><th>Received by</th><th>Amount</th></tr></thead><tbody><?php foreach($payments as $x):?><tr><td><?=app_date($x['paid_at'])?></td><td><?=e($x['location'])?></td><td><?=e($x['payment_method'])?></td><td><?=e($x['reference_no']?:'—')?></td><td><?=e($x['received_by'])?></td><td class="fw-bold text-success"><?=money($x['amount'])?></td></tr><?php endforeach?></tbody></table></div></div><?php require __DIR__.'/partials/footer.php';?>
